=== zimmBreadcrumbs/index.tsx as built in PR #125 ===
import React from 'react';
import { chakra, useMultiStyleConfig, type SystemStyleObject } from '@chakra-ui/react';

const RECIPE = 'ZimmBreadcrumbs';

export type BreadcrumbItem = {
  label: string;
  /** When provided renders the item as a link. */
  href?: string;
};

export type ZimmBreadcrumbsProps = {
  /** Ordered list of breadcrumb segments — e.g. [{label:'HOME',href:'/'},{label:'SEARCH RESULTS FOR "SWIM"'}] */
  items: BreadcrumbItem[];
  /** Optional SEO body copy shown to the right of the breadcrumb trail. */
  seoText?: string;
  /** Href for the READ MORE link shown below seoText. Only rendered when seoText is also provided. */
  seoReadMoreHref?: string;
  /** Label for the READ MORE link. Defaults to 'READ MORE'. */
  seoReadMoreLabel?: string;
};

/**
 * Molecule — breadcrumb trail with an optional SEO text column, rendered between the
 * search results grid and the site footer. Figma: Breadcrumbs/SEO (node 40000440-3467).
 *
 * @param props see ZimmBreadcrumbsProps
 */
export const ZimmBreadcrumbs = ({
  items,
  seoText,
  seoReadMoreHref,
  seoReadMoreLabel = 'READ MORE',
}: ZimmBreadcrumbsProps) => {
  const styles = useMultiStyleConfig(RECIPE, {}) as Record<string, SystemStyleObject>;

  const breadcrumbText = items
    .map((item) => item.label.toUpperCase())
    .join('  /  ');

  return (
    <chakra.div __css={styles.container}>
      <chakra.div __css={styles.inner}>
        {/* Breadcrumb trail — rendered as a nav for accessibility */}
        <chakra.nav aria-label="Breadcrumb" __css={styles.breadcrumb}>
          {items.map((item, index) => (
            <React.Fragment key={index}>
              {index > 0 && <chakra.span aria-hidden="true">{'  /  '}</chakra.span>}
              {item.href ? (
                <chakra.a href={item.href}>{item.label.toUpperCase()}</chakra.a>
              ) : (
                <chakra.span aria-current={index === items.length - 1 ? 'page' : undefined}>
                  {item.label.toUpperCase()}
                </chakra.span>
              )}
            </React.Fragment>
          ))}
        </chakra.nav>

        {seoText && (
          <chakra.div __css={styles.seoContent}>
            <chakra.p __css={styles.seoText}>{seoText}</chakra.p>
            {seoReadMoreHref && (
              <chakra.a href={seoReadMoreHref} __css={styles.readMore}>
                {seoReadMoreLabel}
              </chakra.a>
            )}
          </chakra.div>
        )}
      </chakra.div>
    </chakra.div>
  );
};

